
const base='/api/scanner/marketing/community';let data;let timer;
async function load(method='GET'){const s=document.querySelector('#status');try{const r=await fetch(base+(method==='POST'?'/verify':''),{method,headers:{'X-Scanner-Request':'1'},signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error(r.status===403?'Этот проект доступен только владельцу панели.':'Не удалось получить состояние: '+r.status);data=await r.json();s.textContent=data.working?'Идёт настройка. Можно оставить эту страницу открытой.':data.status==='ready'?'Сообщество настроено. Вход свободный.':(data.retry_after>0?'Telegram просит подождать '+Math.ceil(data.retry_after/60)+' мин. Повторные запросы приостановлены.':data.error==='FloodWaitError'?'Telegram ограничил частоту запросов. Настройка ещё не завершена.':data.error)||'Настройка сообщества ещё не завершена.';const join=document.querySelector('#join');join.hidden=!data.invite_link;join.href=data.invite_link||'#';join.textContent=data.invite_link||'';document.querySelector('#copy').hidden=!data.invite_link;document.querySelector('#verify').disabled=!data.chat_id||data.retry_after>0||data.working;const resume=document.querySelector('#resume');resume.hidden=data.status==='ready';resume.disabled=data.retry_after>0||data.working;clearTimeout(timer);if(data.working||data.retry_after>0)timer=setTimeout(()=>load(),15000);const list=document.querySelector('#topics');list.replaceChildren();for(const [title,id] of Object.entries(data.topics||{})){const li=document.createElement('li'),a=document.createElement('a');a.textContent=title;a.href='https://t.me/c/'+String(data.chat_id).replace('-100','')+'/'+id;a.target='_blank';a.rel='noopener';li.append(a);list.append(li)}document.querySelector('#materials').textContent='Сохранено публикаций: '+Object.keys(data.posts||{}).length;}catch(e){s.textContent=e.message}}
document.querySelector('#verify').onclick=async e=>{e.target.disabled=true;await load('POST');e.target.disabled=false};document.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(data.invite_link);document.querySelector('#copy-status').textContent='Ссылка скопирована.'}catch{document.querySelector('#copy-status').textContent='Скопируйте ссылку выше вручную.'}};load();

document.querySelector('#resume').onclick=async e=>{e.target.disabled=true;try{const r=await fetch(base+'/launch',{method:'POST',headers:{'X-Scanner-Request':'1'},signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('Запуск недоступен: '+r.status);await load()}catch(err){document.querySelector('#status').textContent=err.message;e.target.disabled=false}};

async function loadClosed(){try{const r=await fetch(base+'/closed',{headers:{'X-Scanner-Request':'1'},signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('Не удалось получить состояние закрытой группы');const d=await r.json();document.querySelector('#closed-status').textContent=d.status==='ready'?'Настроена. Вступление по заявке, после вашего одобрения.':d.working?'Готовим темы и материалы.':d.retry_after>0?'Telegram временно ограничил запросы. Настройка ожидает продолжения.':'Настройка ещё не завершена.';const a=document.querySelector('#closed-link');if(d.chat_id){a.href='https://t.me/c/'+String(d.chat_id).replace('-100','')+'/1';a.hidden=false}if(d.working)setTimeout(loadClosed,15000)}catch(e){document.querySelector('#closed-status').textContent=e.message}}loadClosed();

let neuroState;
async function loadNeuro(){try{const r=await fetch(base+'/neurovlad',{headers:{'X-Scanner-Request':'1'},signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('Не удалось получить состояние НейроРазработчика');neuroState=await r.json();const d=neuroState;document.querySelector('#neuro-status').textContent=(d.enabled?'Ответы включены.':'Автоматические ответы выключены.')+' '+(d.error||'')+' Запросов сегодня: '+d.today_calls+' из '+d.daily_limit+'. На участника: '+d.per_person_limit+'.';const a=document.querySelector('#neuro-link');if(d.chat_id&&d.topic_id){a.href='https://t.me/c/'+String(d.chat_id).replace('-100','')+'/'+d.topic_id;a.hidden=false}const b=document.querySelector('#neuro-toggle');b.textContent=d.enabled?'Выключить ответы':'Включить ответы';b.disabled=!d.enabled&&(!d.provider_verified||!d.topic_id)}catch(e){document.querySelector('#neuro-status').textContent=e.message}}
async function neuroAction(path,body){const r=await fetch(base+'/neurovlad/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Scanner-Request':'1'},body:JSON.stringify(body),signal:AbortSignal.timeout(60000)});const d=await r.json();if(!r.ok)throw Error(d.detail||'Не удалось выполнить действие');return d}
document.querySelector('#neuro-test').onclick=async e=>{e.target.disabled=true;try{const d=await neuroAction('test',{text:'Как подготовить одну небольшую учебную задачу для AI?'});document.querySelector('#neuro-test-result').textContent='Подключение проверено. Пример ответа: '+d.answer.text}catch(err){document.querySelector('#neuro-test-result').textContent=err.message}finally{e.target.disabled=false;await loadNeuro()}};
document.querySelector('#neuro-toggle').onclick=async e=>{e.target.disabled=true;try{await neuroAction('control',{enabled:!neuroState.enabled})}catch(err){document.querySelector('#neuro-test-result').textContent=err.message}finally{await loadNeuro()}};loadNeuro();
